T[1] = { { "Nova de Fogo", "Dano de Fogo em todos que estiverem perto dele, várias vezes por combate. Como curador, mantenha o corpo a corpo com a vida cheia." }, { "Gancho de Direita", "Um golpe forte que arremessa o tanque para longe." } }
T[2] = { { "Imolação", "Queima um jogador, depois causa dano de Fogo a cada poucos segundos por 21 segundos. Interrompa a magia ou dissipe a queimadura." }, { "Maldição da Fraqueza", "Reduz o dano físico de um jogador por 30 segundos. Um mago ou druida pode removê-la." } }
