T[4] = { { "Veneno", "Os golpes dele envenenam: dano de Natureza ao longo do tempo. Cure o veneno se puder." }, { "Ataque Pérfido", "Dano extra no tanque a cada 5 a 15 segundos." } }
T[5] = { { "Maldições e doenças", "Remover uma maldição ou curar uma doença ajuda bastante. Fora isso, é um combate fácil: limpe a sala antes de começar." } }
T[6] = { { "O invocador", "Mate primeiro o invocador: ele traz reforços. Depois o elemental." }, { "Fogo por toda parte", "Dano em área no grupo, pior quando o grupo luta muito no corpo a corpo." } }
T[7] = { { "Arremessado pela sala", "Ele lança os jogadores pela sala. Limpe os grupos mais próximos e tanke-o perto do túnel, para que ninguém caia em outro grupo." } }
T[8] = { { "Medo quando enfraquece", "Quando a vida dele cai, ele aterroriza o grupo inteiro. Leve algo para quebrar o medo, ou limpe a sala antes para que ninguém corra para cima de outros inimigos." }, { "Os cofres fechados", "Após o combate, abra os cofres da sala: cerca de 24 Dwarven Heirlooms para Important Heirlooms, e a tábua de The Treaty of Understanding." } }
