T[10] = { note = "Limpe o pátio, clique na estátua e resista durante as ondas: ela chega depois.", { "Nova de Gelo", "Dano de Gelo no grupo todo. Se você cura, guarde mana para todas as ondas." } }
T[11] = { { "Arremessado para o alto", "Lança o tanque para o alto e o atordoa por 5 segundos. Cuidado com a ameaça dos jogadores de dano: o tanque só o segura por cerca de metade do combate." }, { "Uma patrulha", "Limpe a sala dele antes de começar: uma patrulha passa por ali. A cabeça dele é coletada para as missões Abominable Creatures e Unending Torment." } }
T[12] = { { "Choque de Chamas", "Sua magia principal. Pode ser interrompida e atordoada: organize interrupções e atordoamentos com o grupo." }, { "Muitos pontos de vida", "O combate mais longo da masmorra. Continue as interrupções até o fim." } }
T[13] = { note = "Limpe a casa e a estátua, clique na lareira e resista durante as ondas. Ele chega depois do último golem de carne.", { "Veneno", "Envenena seu alvo. Fique de olho nas barras de vida." }, { "Golpes poderosos", "Ele bate forte: mantenha o tanque vivo. Leve poções de mana para as ondas antes dele." } }
T[14] = { { "Repulsão", "Ele repele: limpe antes os grupos ao redor dele, senão você cai em um deles." }, { "Escudo Antimagia", "Protege-se por um tempo contra magias." }, { "Golpes poderosos", "Ele bate forte: mantenha o tanque com a vida cheia." } }
T[15] = { { "Rajada de Raios", "Ele mantém distância para lançá-la. Interrompa-o." }, { "Toque Curativo", "Cura a si mesmo ou a um aliado (conjuração de 3 segundos). Interrompa-o." }, { "Forma de Serpente de Cobrahn", "Com 30% de vida, ele se transforma em serpente: golpes mais lentos, porém mais pesados, e começa a fazer jogadores dormirem." } }
T[16] = { { "Toque Curativo", "Cura a si mesma ou a um aliado. Interrompa-a." }, { "Sono", "Faz um jogador dormir por até 20 segundos. Dano o acorda, e uma Dissipar Magia o remove." }, { "Aura de Espinhos", "Dano de Natureza em quem a atacar no corpo a corpo." } }
T[17] = { { "Carapace Escudo", "Por 12 segundos, ele sofre 60% menos dano e ataca mais devagar, porém mais forte." } }
T[18] = { { "Trovoada", "Dano de Natureza em todos que estiverem perto dele, depois ataques e movimento reduzidos por 10 segundos." }, { "Toque Curativo", "Cura a si mesmo ou a um aliado. Interrompa-o." }, { "Sono", "Faz um jogador dormir por até 20 segundos." } }
T[19] = { { "Raios em Cadeia", "Um raio que salta para um segundo jogador. Interrompa-o." } }
