T[21] = { { "Vinhas Vorazes", "Quando o alvo dele está por perto, ele derruba e imobiliza todos que estiverem perto dele por 10 segundos. À distância, mantenha a distância." } }
T[22] = { note = "Mate Lady Anacondra, Lorde Cobrahn, Lorde Pythas e Lorde Serpentis, depois fale com o discípulo de Naralex na entrada e escolte-o até Naralex. Proteja-o durante o ritual: Mutanus chega no final.", { "Trovão Estrondoso", "Dano de Natureza em todos que estiverem perto dele e um atordoamento de 2,5 segundos." }, { "Pesadelo de Naralex", "Faz um jogador dormir por até 15 segundos." }, { "Aterrorizar", "Faz um jogador fugir de medo por 4 segundos." } }
T[23] = { { "Golpe de Rhahk'Zor", "Atinge o tanque com força e o atordoa por 3 segundos." } }
T[24] = { { "Perfurar Armadura", "Reduz a armadura do tanque em 75% por 20 segundos." }, { "Foge para buscar ajuda", "Com 15% de vida, ele foge para buscar ajuda. Acabe com ele antes que se afaste." } }
