T[30] = { { "Surrar", "De tempos em tempos, dois ataques extras: golpes fortes no tanque." }, { "Aliados de VanCleef", "Na metade da vida, ele chama dois Gatunos Defias." } }
T[31] = { { "Jato de Ácido", "Dano de Natureza a cada 5 segundos por 30 segundos em todos que estiverem perto dele." }, { "Culinária do Cookie", "Abaixo de metade da vida, ele se cura (conjuração de 2 segundos). Interrompa-o." }, { "Foge para buscar ajuda", "Com 15% de vida, ele foge para buscar ajuda. Acabe com ele antes que se afaste." } }
