T[36] = { { "Luz Sagrada", "Cura a si mesmo ou a um aliado (conjuração de 2,5 segundos). Interrompa-o." }, { "Escudo Divino", "Torna-o imune a todo dano e a todas as magias por 10 segundos." }, { "Martelo da Justiça", "Atordoa um jogador por 4 segundos." } }
T[37] = { { "Pede ajuda", "Quando você o ataca, ele chama as criaturas a até 30 metros. Limpe ao redor dele antes." }, { "Fúria Uivante", "Com 60%, 40% e 20% de vida, os golpes dele ficam mais fortes." } }
T[38] = { { "Atacar Múltiplos", "Atinge seu alvo e o jogador mais próximo dele." }, { "Quebra-joelho", "Reduz a velocidade de movimento do alvo por 10 segundos." } }
T[39] = { note = "Eles chegam em quatro depois da morte de Fenrus, o Devorador: Arugal aparece por um instante e os chama.", { "Oferenda Sombria", "Cura outro andarilho do Vácuo. Matem-nos um por um." } }
T[40] = { { "Baba Tóxica", "Dano de Natureza a cada 6 segundos e mana drenada, por 2 minutos. Cure o veneno." } }
T[41] = { { "Lobos de reforço", "Quanto mais o combate dura, mais lobos ele tem ao lado: um worg pálido após 30 a 45 segundos, depois um worg espumante, depois um horror lupino." } }
T[42] = { { "Seta do Vácuo", "Um projétil de Sombra de 3 segundos no tanque, repetidamente. Interrompa-o." }, { "Maldição de Arugal", "Transforma um jogador que não seja o tanque em um Glutão de Presanegra que luta por ele por 10 segundos. Remova a maldição." }, { "Passo Sombrio", "Ele se teletransporta entre sua plataforma, a plataforma de cima e a escada." }, { "Trovoada", "Quando o tanque chega nele: dano de Natureza e um atordoamento de 5 segundos ao redor dele." } }
T[43] = { { "Pisotear", "Atinge todos que estiverem perto dele." } }
T[44] = { { "Relâmpago Bifurcado", "Dano de Natureza em um cone à frente dela (conjuração de 2 segundos). Fique fora do cone." }, { "Nova de Gelo", "Congela no lugar todos que estiverem perto dela por até 8 segundos." }, { "Lentidão", "Reduz a velocidade de movimento e de ataque de um jogador por 10 segundos." } }
T[45] = { { "Rede", "Imobiliza um jogador no lugar por 10 segundos." } }
T[46] = { note = "Clique na pedra da Brasse na água: ele surge dela.", { "Seta de Gelo", "Ele mantém distância para lançá-la: dano de Gelo e lentidão." }, { "Nova de Gelo", "Imobiliza todos que estiverem perto dele por até 8 segundos." } }
T[47] = { { "Sono", "Faz dormir todos que estiverem perto dele por até 10 segundos. Dano acorda quem dorme." }, { "Ataque Mental", "Dano de Sombra em um jogador (conjuração de 1,5 segundo)." } }
T[48] = { note = "Ele espera em uma caverna submersa, sob o templo do Lorde do Crepúsculo Kelris, e muitos grupos o perdem. Nade sob o templo para chegar até ele." }
T[49] = { note = "Com o Lorde do Crepúsculo Kelris morto, acenda as quatro Chamas de Aku'mai da sala dele, uma após a outra. Cada uma traz uma onda de criaturas. Quando todas estiverem mortas, a porta de Aku'mai se abre.", { "Nuvem Venenosa", "Dano de Natureza a cada 5 segundos por 45 segundos em todos que estiverem por perto." }, { "Fúria Frenética", "Abaixo de 30% de vida: rajadas de ataques 75% mais rápidos, repetidamente." } }
T[50] = { { "Escudo Relâmpago", "Raios atingem quem o tocar. Um sacerdote ou xamã pode removê-lo." }, { "Rajada de Raios", "Ele mantém distância para lançá-la. Interrompa-o." } }
T[51] = { { "Pancada de Escudo", "Atinge o tanque e o atordoa por 2 segundos." }, { "Foge para buscar ajuda", "Com 15% de vida, ele foge para buscar ajuda. Acabe com ele antes que se afaste." } }
T[52] = { { "Foge para buscar ajuda", "Com 15% de vida, ele foge para buscar ajuda. Acabe com ele antes que se afaste." } }
T[53] = { { "Surrar", "De tempos em tempos, dois ataques extras: golpes fortes no tanque." }, { "Enfurecer", "Com 30% de vida, ele ataca 30% mais rápido até o fim do combate." } }
T[54] = { { "Corrente de Raios", "Um raio que salta de jogador em jogador (conjuração de 2 segundos). Interrompa-o." }, { "Sede de Sangue", "Acelera os ataques dele ou de um aliado em 30% por 30 segundos. Um sacerdote ou xamã pode removê-la." } }
T[55] = { { "Bomba de Fumaça", "Atordoa todos que estiverem perto dele por 4 segundos." }, { "Grito de Guerra", "Mais poder de ataque para ele e seus aliados por 2 minutos." }, { "Foge para buscar ajuda", "Com 15% de vida, ele foge para buscar ajuda. Acabe com ele antes que se afaste." } }
T[56] = { { "Golpear", "Atinge o alvo com o dano da arma mais 5. Mantenha o tanque vivo." } }
T[57] = { { "Muitos pontos de vida", "Nada de especial visto durante o combate: ele bate e tem muita vida. Ele ronda o pântano do início entre crocolisco elite, então limpe-os primeiro ou o atraia para longe deles." } }
T[58] = { note = "Mate a matriarca dos raptores no capim alto. Uma onda de raptores chega quando ela morre, e Dente-Sombrio corre até vocês depois que todos morrem.", { "Raptores no capim", "Pequenos raptores saltam do capim quando você o atravessa e fazem você sangrar." }, { "A onda antes dele", "Mate todos os raptores da onda antes que ele chegue. Um grupo morreu na primeira tentativa com Dente-Sombrio e vários raptores em cima dele ao mesmo tempo." }, { "Medo", "O tanque é amedrontado várias vezes durante esse combate. O Totem de Tremor de um xamã ajuda." } }
T[59] = { note = "Ele fica parado no fim do caminho das aranhas. Clique no pequeno painel ao lado dele para acordá-lo.", { "Redefinição de ameaça", "Ele zera a ameaça e troca de alvo durante o combate. Dano, desacelerem quando o tanque o perder. Tanque, retome-o imediatamente." } }
T[60] = { { "O acampamento Bocadragão", "Ele fica num acampamento Bocadragão. Os grupos dele são fáceis de puxar um por um: pegue-os primeiro um de cada vez. O combate em si é curto, nada de especial visto até agora." } }
T[61] = { note = "Ele fica perto de um círculo ritual nos esgotos, cercado por necromantes do Kirin Tor.", { "Frenesi Profano", "Acelera os ataques dele em 75% por 20 segundos. É magia: a Expiação de um xamã ou o Dissipar Magia de um sacerdote o remove." }, { "Espancar", "De vez em quando ele ataca duas vezes a mais com um só golpe, e Golpear adiciona dano ao golpe seguinte: o tanque recebe golpes pesados." }, { "Levantar Mortos", "Esqueletos se levantam sem parar ao redor do círculo durante o combate. São fracos: mate-os conforme chegam." }, { "Desarmar", "Desarma o tanque por cerca de 6 segundos." } }
T[62] = { { "Explosão Concentrada", "Após 3 segundos de conjuração, um raio sai à frente dele por 6 segundos e atinge quatro vezes por segundo. Saia da trajetória assim que a conjuração começar." }, { "Seta Arcana", "O ataque dele no tanque entre dois raios, 1,5 segundo de conjuração." } }
T[63] = { { "Manamorfose", "Transforma um jogador em animal por 8 segundos. É magia: dissipe-a." }, { "Silêncio", "Silencia por 10 segundos. Curadores, mantenham distância." }, { "Arcane Manalings", "Ele chama pequenos Arcane Manalings sem parar. Mate-os com dano em área." } }
T[64] = { { "Mau Funcionamento", "2 segundos de conjuração e, por 6 segundos, energia arcana atinge todos a até 25 metros a cada 2 segundos, causando cerca de 140 de dano a cada vez. À distância, fiquem além de 25 metros; no corpo a corpo, saiam durante a conjuração." }, { "Angry Tomes", "Angry Tomes avançam em você pelo caminho. Mate-os antes de engajar o chefe." } }
T[65] = { { "Debilitar", "2 segundos de conjuração: uma energia arcana drena até 200 pontos de mana de todos a até 45 metros dele." }, { "Drenar Vitalidade", "Um efeito mágico no tanque: cerca de 65 de dano Arcano a cada 2 segundos por 10 segundos. Dissipe-o." }, { "A sala dele", "As criaturas ainda vivas na sala dele entram na luta quando você o engaja. Limpe a sala primeiro." } }
T[66] = { note = "Ele espera atrás de uma barreira mágica no centro da cidade, guardada por Suffused Treants. Mate os ents, depois fale com o magus Fansy Goodbringer, logo ao sul da barreira: ele a derruba.", { "Madeira Vil", "Trepadeiras disparam em direção a um jogador e atingem todos a até 5 metros dele, depois deixam vapores tóxicos no chão. Saia dos vapores." }, { "Pisotear", "Ele pisoteia os jogadores ao lado dele, causando cerca de 100 de dano físico." }, { "Emaranhar", "Prende até dois jogadores perto dele por alguns segundos e os fere ao longo do tempo. É magia: dissipem-na." } }
T[67] = { note = "Ela não está lá no início. Nos esgotos, depois de Atrexis, limpe a sala a nordeste, a das barracas de mercado com um pequeno círculo de invocação rosa (não o grande círculo de Atrexis). Um jogador que esteja com o Tomo de Dalaran clica então no círculo, e Lyn sai pelo grande portão redondo gradeado. Para obter o tomo, pegue o Tomo Negro sobre a mesa da sala do arquimago Arugal, na Masmorra de Presa Negra, depois de matar Arugal, e use-o no Leyline Focus, um cristal azul numa sala dos fundos do Moinho Âmbar, na Floresta de Argêntea.", { "Salva de Setas Sombrias", "Setas sombrias em todos a até 30 metros dela." }, { "Maldição dos Espinhos", "1,5 segundo de conjuração: uma maldição de 3 minutos que fere o jogador de vez em quando quando ele ataca. Remova-a." }, { "Esqueletos", "Esqueletos se levantam e lutam ao lado dela. Mate-os." } }
T[68] = { note = "O arquimago Modera abre para o grupo um portal para a câmara púrpura: ele leva até ele.", { "Mana Saltitante", "Uma esfera avança em direção a um jogador aleatório e depois volta para ele. Todos que ela atravessa sofrem dano Arcano e ficam silenciados por 6 segundos: não fique entre ele e esse jogador." }, { "Polimorfia em Massa", "Quando fica sem mana, ele transforma o grupo inteiro em animais por 8 segundos, depois canaliza Evocação por 6 segundos para recuperá-la." }, { "Lentidão", "Reduz a velocidade de todos ao redor dele por 3 segundos: ataques e conjurações 30% mais lentos, movimento 70% mais lento." }, { "Fiquem na sala", "Se alguém sair da sala durante o combate, ele volta com a vida cheia." } }
T[69] = { { "Rede", "Imobiliza todos que estiverem perto dele por 10 segundos." }, { "Lentidão", "Reduz a velocidade de ataque e de movimento de um jogador por 10 segundos, e pode atordoá-lo." }, { "Invocar Barata Mecânica", "Chama baratas mecânicas. A Atualização dele as mata e o cura." } }
T[70] = { note = "Fale com a especialista em demolição Emi Shortfuse e proteja-a enquanto ela explode as duas entradas da caverna. Troggs chegam em ondas, depois Grubbis vem com Chomper." }
T[71] = { { "Megavolt", "Dano de Natureza em um cone à frente dele (conjuração de 2 segundos). Só o tanque fica à frente." }, { "Corrente de Raios", "Um raio que salta entre jogadores próximos (conjuração de 2,5 segundos). Interrompa-o." } }
T[72] = { { "Ceifar Multidão", "Atinge todos que estiverem perto dele e interrompe suas magias. Conjuradores e curadores, mantenham distância." }, { "Golpe Varredor", "Atinge todos em um cone à frente dele." }, { "Pisotear", "Atinge todos que estiverem perto dele." } }
T[73] = { { "Invocar Servo Flamejante", "Chama dois servos flamejantes no início do combate." }, { "Bola de Fogo", "Ele mantém distância para lançá-la. Interrompa-o." }, { "Escudo de Fogo II", "Dano de Fogo em todos que estiverem perto dele por um minuto. Um sacerdote ou xamã pode removê-lo." } }
T[74] = { { "Bombas Ambulantes", "Ele acende uma a uma as cabeças de gnomo ao redor da sala, e cada uma solta bombas ambulantes que explodem ao alcançar um jogador. O botão ao lado de uma cabeça a apaga. Abaixo de metade da vida, ele as acende mais rápido." }, { "Repelir", "Arremessa o tanque para longe. Abaixo de metade da vida, atinge todos ao redor dele." } }
T[75] = { { "Invocar Espírito de Javali", "Chama um Espírito de Javali para o lado dele a cada 30 a 45 segundos (conjuração de 1,5 segundo). Mate cada um antes que o próximo chegue." }, { "Rajada de Cura", "Abaixo de 75% de vida, ele se cura, e a cura salta para dois aliados próximos (conjuração de 2,5 segundos). Interrompa-o." } }
T[76] = { { "Dominar Mente", "Assume o controle de um jogador que não seja o alvo dele por 15 segundos (conjuração de 2 segundos). Interrompa-o ou dissipe o efeito no jogador." }, { "Seta Sombria", "Ele mantém distância para lançá-la. Interrompa-o." } }
T[77] = { { "Pede ajuda", "Quando você o engaja, ele chama as criaturas a até 15 metros, incluindo os dois Lançadores Presacerta ao lado dele. Mantenha um dos dois sob controle durante o combate." }, { "Trovão", "A cada 8 a 14 segundos: dano de Natureza em todos perto dele, e os ataques e movimentos deles ficam mais lentos por 10 segundos." } }
T[78] = { { "Carga Giratória", "Atinge todos que estiverem perto dele." }, { "Aura de Espinhos", "Quem atingir ele ou um aliado próximo (incluindo o Lorde Supremo Marretusco) sofre dano de Natureza." } }
T[79] = { note = "Uma proteção fecha a caverna dele. Mate os dois Guardiões Caveira Morta posicionados na frente: ela cai quando os dois morrem.", { "Deixado para Morrer", "A cada 21 a 35 segundos, ele ataca um jogador que não seja o alvo dele, que cai como morto e não pode mais atacar nem lançar feitiços. Se mover acaba com o efeito." }, { "Devastar", "A cada 25 a 31 segundos: atinge todos perto dele e os atordoa por 2,5 segundos." }, { "Enfurecer", "A 60% de vida e depois a 40%, ele ataca 60% mais rápido e bate mais forte por 2 minutos." } }
T[80] = { note = "Um morcego raro: ele não aparece em todas as passagens. Quando está lá, espera num pequeno recuo da parede da caverna dos morcegos, perto de Charlga Talhaflanco." }
T[81] = { { "Corrente de Relâmpagos", "Ela mantém distância e a lança sem parar: um raio que salta entre até 3 jogadores (conjuração de 2,5 segundos). Interrompa-a." }, { "Pureza", "A cada 9 a 15 segundos, ela fica imune a todos os ataques e feitiços por 2 segundos." }, { "Renovar", "Cura um aliado ferido, ou ela mesma, ao longo de 15 segundos. Um sacerdote ou xamã pode removê-lo." } }
T[82] = { { "Invocar Ribombante da Terra", "Um Ribombante de Pedra o acompanha e luta ao lado dele." }, { "Relâmpago", "Ele mantém distância para lançá-lo. Interrompa-o." }, { "Foge para buscar ajuda", "A 15% de vida, ele foge para buscar ajuda. Termine-o antes que ele se afaste." } }
