T[87] = { note = "Mais ou menos uma partida em três, um dos três raros do cemitério fica num dos seis locais do mapa: Azshir the Sleepless, Fallen Champion ou Ironspine.", { "Maldição da Fraqueza", "Reduz o dano físico de todos a até 30 metros por 2 minutos. Um mago ou druida pode removê-la." }, { "Nuvem Venenosa", "Dano de Natureza a cada 5 segundos por 45 segundos em todos que estiverem perto." } }
T[88] = { { "Farpas Flamejantes", "Uma coluna de chamas onde um jogador está (conjuração de 3 segundos): dano de Fogo e depois de novo a cada 3 segundos por 9 segundos. Saia dela." }, { "Nova de Fogo", "Dano de Fogo em todos a até 10 metros dele." }, { "Choque Flamejante", "Dano de Fogo em um jogador e depois de novo a cada 3 segundos por 12 segundos. Um Dissipar Magia o remove." }, { "Seta Sombria", "Ele mantém distância para lançá-la. Interrompa-o." } }
