T[90] = { { "Detonação", "Na metade da vida, ele se tranca por 8 segundos numa Bolha Arcana e lança Detonação (conjuração de 5 segundos): dano de Fogo pesado em todos a até 30 metros. Saia do alcance antes da explosão e depois volte." }, { "Polimorfia", "Transforma em ovelha um jogador que não seja o alvo dele por até 20 segundos (conjuração de 1,5 segundo). Interrompa-o ou dissipe o efeito no jogador." }, { "Silêncio", "Silencia todos a até 15 metros por 10 segundos (conjuração de 1,5 segundo). Se você cura, fique mais longe." }, { "Explosão Arcana", "A cada poucos segundos, dano Arcano em todos a até 10 metros. À distância, mantenha-se afastado." } }
